import{_ as r,o,c as t,a2 as a}from"./chunks/framework.DzNHXt93.js";const v=JSON.parse('{"title":"Decision 0001 — Version provider runner reports separately","description":"","frontmatter":{},"headers":[],"relativePath":"spec/trust/0001-provider-runner-report-v2.md","filePath":"spec/trust/0001-provider-runner-report-v2.md"}'),i={name:"spec/trust/0001-provider-runner-report-v2.md"};function n(s,e,d,c,p,l){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="decision-0001-—-version-provider-runner-reports-separately" tabindex="-1">Decision 0001 — Version provider runner reports separately <a class="header-anchor" href="#decision-0001-—-version-provider-runner-reports-separately" aria-label="Permalink to &quot;Decision 0001 — Version provider runner reports separately&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-07-29</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The original <code>takoform.standard-runner-report@v1</code> format is shared by host and provider evidence and is strictly decoded. Adding a provider binary digest to that object would make newly signed bytes invalid to an existing v1 verifier because unknown fields fail closed.</p><p>Provider report tooling can also advance after a provider release without changing the provider executable. Comparing the tooling source commit to the provider release commit therefore rejects valid evidence and does not prove which bytes actually ran.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Host reports keep <code>takoform.standard-runner-report@v1</code>. Historical provider v1 reports remain readable for their retained admission generation.</p><p>New provider reports use <code>takoform.standard-provider-runner-report@v2</code> and require <code>providerBinarySha256</code>. Current admission requires one digest across the full provider report closure and exact equality with every direct Registry installation readback.</p><p>The machine-readable contract lock is <code>spec/trust/profile.json</code> schema v2. Unknown fields remain rejected for both formats.</p>',9)])])}const h=r(i,[["render",n]]);export{v as __pageData,h as default};
